import{_ as i,o as a,c as t,a0 as r}from"./chunks/framework.B7o6dWmz.js";const s="/blog-styles/01-paul-graham.png",o="/blog-styles/02-ruanyifeng.png",e="/blog-styles/03-simon-willison.png",n="/blog-styles/04-vercel.png",h="/blog-styles/05-stripe.png",g="/blog-styles/06-wait-but-why.png",p="/blog-styles/07-sspai.png",f=JSON.parse('{"title":"博客风格样板（供挑选）","description":"","frontmatter":{},"headers":[],"relativePath":"styles.md","filePath":"styles.md"}'),c={name:"styles.md"};function u(_,l,m,d,b,q){return a(),t("div",null,[...l[0]||(l[0]=[r('<h1 id="博客风格样板-供挑选" tabindex="-1">博客风格样板（供挑选） <a class="header-anchor" href="#博客风格样板-供挑选" aria-label="Permalink to &quot;博客风格样板（供挑选）&quot;">​</a></h1><p>从全球著名博客里挑了 <strong>7 种典型设计风格</strong>，附首页整页截图。你挑 2–3 个喜欢的，我仿照其风格重建本站（配色 / 布局 / 字体 / 文章排版）。</p><p>每个样板标注了：<strong>风格类型 · 设计特点 · 适合的内容形态</strong>。</p><hr><h2 id="_01-·-paul-graham-—-极简纯文字型" tabindex="-1">01 · Paul Graham — 极简纯文字型 <a class="header-anchor" href="#_01-·-paul-graham-—-极简纯文字型" aria-label="Permalink to &quot;01 · Paul Graham — 极简纯文字型&quot;">​</a></h2><ul><li>建站：手写 HTML，无框架（经典中的经典）</li><li>风格：白底黑字，几乎无样式；<strong>内容即设计</strong></li><li>特点：加载极快、零干扰、权威感强</li><li>适合：深度思考长文、个人随笔、观点连载</li></ul><p><img src="'+s+'" alt="Paul Graham"></p><h2 id="_02-·-阮一峰的网络日志-—-中文经典极简" tabindex="-1">02 · 阮一峰的网络日志 — 中文经典极简 <a class="header-anchor" href="#_02-·-阮一峰的网络日志-—-中文经典极简" aria-label="Permalink to &quot;02 · 阮一峰的网络日志 — 中文经典极简&quot;">​</a></h2><ul><li>建站：自建静态站，朴素表格布局</li><li>风格：单栏文字流，年代感配色，<strong>中文技术博客天花板之一</strong></li><li>特点：十几年稳定输出，「每周分享」栏目形态值得借鉴</li><li>适合：技术周刊、入门教程、工具分享</li></ul><p><img src="'+o+'" alt="阮一峰"></p><h2 id="_03-·-simon-willison-—-ai-主题个人博客" tabindex="-1">03 · Simon Willison — AI 主题个人博客 <a class="header-anchor" href="#_03-·-simon-willison-—-ai-主题个人博客" aria-label="Permalink to &quot;03 · Simon Willison — AI 主题个人博客&quot;">​</a></h2><ul><li>建站：Django 自建 + 标签/搜索体系</li><li>风格：<strong>信息密度高</strong>的单栏列表，每条有日期、标签、摘要</li><li>特点：全球 AI 领域被引用最多的个人博客之一；「短内容+外链+评论」模式</li><li>适合：AI 日报、工具实测、链接聚合（与我们定位最接近）</li></ul><p><img src="'+e+'" alt="Simon Willison"></p><h2 id="_04-·-vercel-—-现代开发者博客" tabindex="-1">04 · Vercel — 现代开发者博客 <a class="header-anchor" href="#_04-·-vercel-—-现代开发者博客" aria-label="Permalink to &quot;04 · Vercel — 现代开发者博客&quot;">​</a></h2><ul><li>建站：Next.js + 自研设计系统</li><li>风格：<strong>黑/白极简 + 网格卡片</strong>，圆角、细边框、留白克制</li><li>特点：开发圈审美标杆；首页大卡片+侧栏精选</li><li>适合：技术深文、产品发布、团队工程实践</li></ul><p><img src="'+n+'" alt="Vercel"></p><h2 id="_05-·-stripe-blog-—-精品企业博客" tabindex="-1">05 · Stripe Blog — 精品企业博客 <a class="header-anchor" href="#_05-·-stripe-blog-—-精品企业博客" aria-label="Permalink to &quot;05 · Stripe Blog — 精品企业博客&quot;">​</a></h2><ul><li>建站：Next.js + 定制化设计</li><li>风格：<strong>大留白、强排版层级、精修配图</strong>，商业感与信任感拉满</li><li>特点：企业博客天花板；「故事+数据」的叙事结构</li><li>适合：商业案例、数据报告、品牌叙事（未来卖产品时最合适）</li></ul><p><img src="'+h+'" alt="Stripe"></p><h2 id="_06-·-wait-but-why-—-长文插画型" tabindex="-1">06 · Wait But Why — 长文插画型 <a class="header-anchor" href="#_06-·-wait-but-why-—-长文插画型" aria-label="Permalink to &quot;06 · Wait But Why — 长文插画型&quot;">​</a></h2><ul><li>建站：WordPress + 手绘插画体系</li><li>风格：<strong>单页超长文 + 自绘示意图</strong>，用漫画讲透复杂话题</li><li>特点：单篇文章全网刷屏级传播；「图示化解释」的鼻祖</li><li>适合：深度科普、机制拆解、复杂概念可视化</li></ul><p><img src="'+g+'" alt="Wait But Why"></p><h2 id="_07-·-少数派-—-中文内容平台" tabindex="-1">07 · 少数派 — 中文内容平台 <a class="header-anchor" href="#_07-·-少数派-—-中文内容平台" aria-label="Permalink to &quot;07 · 少数派 — 中文内容平台&quot;">​</a></h2><ul><li>建站：自研平台</li><li>风格：<strong>杂志式卡片流</strong>，多栏目、标签、搜索、作者体系齐全</li><li>特点：中文「效率/品质生活」内容头部；适合多人/多栏目运营</li><li>适合：多作者投稿、教程合集、工具评测</li></ul><p><img src="'+p+'" alt="少数派"></p><hr><blockquote><p>挑选建议：站内文章形态决定风格——若主打<strong>深度实战文 + 未来卖工具</strong>，01/03/05 是稳妥组合；若想<strong>技术圈审美</strong>，选 04；若想<strong>漫画式科普</strong>，选 06。</p></blockquote>',27)])])}const P=i(c,[["render",u]]);export{f as __pageData,P as default};
